package Hello_world;
/* write a java code to print pattern 55555    
44444
33333
22222
11111
*/

public class A005_patter4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=5;
		for (int i = n; i >=1; i--) {
			for (int j = n; j >=1; j--) {
				System.out.print(i);
				
			}System.out.println();
			
			
		}
		

	}

}
